use crate::layout::{Layout,Rect};#[derive(Debug,Clone,Copy,PartialEq,Eq)]pub enum TitlebarAction{Drag,Minimize,Maximize,Close,None}pub fn action_at(l:Layout,x:i32,y:i32)->TitlebarAction{let(a,b,c)=l.titlebar_button_rects();if a.contains(x,y){TitlebarAction::Minimize}else if b.contains(x,y){TitlebarAction::Maximize}else if c.contains(x,y){TitlebarAction::Close}else if l.titlebar.contains(x,y){TitlebarAction::Drag}else{TitlebarAction::None}}pub fn title_rect(l:Layout)->Rect{let(a,_,_)=l.titlebar_button_rects();Rect::new(16,0,(a.x-24).max(0),32)}
